def calculate_tax_bracket(income: float, brackets: list[tuple[float, float]]) -> float:
    if income <= 0:
        return 0.0

    total_tax = 0.0
    for upper_limit, rate in brackets:
        if income <= upper_limit:
            total_tax += (income - (income if income < upper_limit else 0)) * rate
            break
        else:
            total_tax += (upper_limit - (income if income < upper_limit else 0)) * rate
            income -= upper_limit

    return round(total_tax, 2)

